import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Entitäten im Batch schreiben","description":"","frontmatter":{"title":"Entitäten im Batch schreiben","covers":{"screens":[],"stories":["US-141","US-036"]}},"headers":[],"relativePath":"de/usage/entities-batch.md","filePath":"de/usage/entities-batch.md"}`),a={name:`de/usage/entities-batch.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="entitaten-im-batch-schreiben" tabindex="-1">Entitäten im Batch schreiben <a class="header-anchor" href="#entitaten-im-batch-schreiben" aria-label="Permalink to “Entitäten im Batch schreiben”">​</a></h1><p>Quellsysteme – ein Repository-Scanner, ein CMDB-Export, ein Skript – legen Entitäten über <code>POST /api/v1/entities/batch</code> an und aktualisieren sie. In dieser Version ist der Aufrufer eine Person mit der Berechtigung <code>entity:write</code> (Rolle <code>enterprise-architect</code>) und einer Sitzung (siehe <a href="./../administration/#api-login">Für die Administration über die API anmelden</a>); Service-Accounts mit Client Credentials folgen in einer späteren Version.</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/entities/batch&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;X-Agent-Id: repo-scanner&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;X-Agent-Run: 2026-10-16-nightly&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;strategy&quot;: &quot;upsert&quot;, &quot;entities&quot;: [{&quot;name&quot;: &quot;CRM System&quot;, &quot;metatypeId&quot;: &quot;&lt;id&gt;&quot;, &quot;externalId&quot;: &quot;git:org/crm&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;properties&quot;: [{&quot;propertyDefId&quot;: &quot;&lt;id of Status&gt;&quot;, &quot;value&quot;: &quot;active&quot;}]}]}&#39;</span></span></code></pre></div><p><code>GET /metamodel/metatypes</code> liefert die IDs der Entitätstypen und ihrer Eigenschaften.</p><h2 id="wie-eintrage-geschrieben-werden" tabindex="-1">Wie Einträge geschrieben werden <a class="header-anchor" href="#wie-eintrage-geschrieben-werden" aria-label="Permalink to “Wie Einträge geschrieben werden”">​</a></h2><ul><li><code>externalId</code> identifiziert eine Entität aus dem Quellsystem. Mit der Strategie <code>upsert</code> legt eine unbekannte ID die Entität an, eine bekannte aktualisiert sie; <code>create-only</code> und <code>skip-existing</code> verhalten sich wie benannt.</li><li>Beim Aktualisieren bleiben Felder und Eigenschaften, die im Eintrag fehlen, unverändert; ein leerer Wert entfernt einen Eigenschaftswert. Ein unveränderter Eintrag wird als <code>unchanged</code> gemeldet und erzeugt keine Version.</li><li>Mit <code>atomic=false</code> (Standard) wird jeder Eintrag einzeln geschrieben, und die Antwort meldet einen Status pro Eintrag. Mit <code>atomic=true</code> werden alle Einträge geschrieben oder keiner (<code>422</code> mit den Fehlern pro Eintrag).</li><li>Ein Request enthält höchstens <code>oea.entities.batch.max-items</code> Entitäten (Standard und Maximum 500) und höchstens 10 MB.</li><li><code>X-Agent-Id</code> und <code>X-Agent-Run</code> werden nur als informative Felder der Audit-Events gespeichert.</li></ul><p>Noch nicht unterstützt: <code>dryRun=true</code>, <code>parentId</code>, <code>lifecycle</code> und Eigenschaften mit eingeschränkter Sichtbarkeit (<code>422</code> oder ein Fehler für den Eintrag).</p><p>Jede geschriebene Entität erzeugt eine neue Version mit den vorherigen Werten der geänderten Felder und das Audit-Event <code>entity.created</code> oder <code>entity.updated</code>.</p><h2 id="connections" tabindex="-1">Verbindungen <a class="header-anchor" href="#connections" aria-label="Permalink to “Verbindungen”">​</a></h2><p>Verbindungen sind Entitäten eines <a href="./../administration/metamodel-editing#connection-types">Verbindungstyps</a> mit genau einer Quelle und einem Ziel. Schicke sie in <code>connections</code> desselben Batches; sie werden nach den Entitäten geschrieben und können daher Entitäten des Batches über ihre externe ID nennen:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/entities/batch&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;strategy&quot;: &quot;upsert&quot;, &quot;atomic&quot;: true,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;entities&quot;: [{&quot;name&quot;: &quot;CRM&quot;, &quot;metatypeId&quot;: &quot;&lt;id&gt;&quot;, &quot;externalId&quot;: &quot;cmdb:crm&quot;},</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">               {&quot;name&quot;: &quot;ERP&quot;, &quot;metatypeId&quot;: &quot;&lt;id&gt;&quot;, &quot;externalId&quot;: &quot;cmdb:erp&quot;}],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;connections&quot;: [{&quot;connectionMetatypeId&quot;: &quot;&lt;id of Data Flow&gt;&quot;, &quot;externalId&quot;: &quot;flow:crm-erp&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">                   &quot;sourceExternalId&quot;: &quot;cmdb:crm&quot;, &quot;targetExternalId&quot;: &quot;cmdb:erp&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">                   &quot;properties&quot;: [{&quot;propertyDefId&quot;: &quot;&lt;id of Protocol&gt;&quot;, &quot;value&quot;: &quot;sftp&quot;}]}]}&#39;</span></span></code></pre></div><ul><li>Nenne Quelle und Ziel entweder über die ID (<code>sourceId</code>, <code>targetId</code>) oder über die externe ID (<code>sourceExternalId</code>, <code>targetExternalId</code>), nicht beides. Eine Verbindung kann an einer anderen Verbindung beginnen oder enden, wenn der Verbindungstyp das erlaubt.</li><li>Ohne <code>name</code> heißt eine neue Verbindung „Name der Quelle → Name des Ziels“.</li><li>Quelle und Ziel lassen sich nicht ändern. Eine bekannte Verbindung mit anderer Quelle oder anderem Ziel zu schicken, ist ein Fehler; schicke sie stattdessen als neue Verbindung. Das Löschen von Verbindungen folgt in einer späteren Version.</li><li>Strategien, Atomarität und die Grenze von 500 gelten für Verbindungen wie für Entitäten. Die Antwort meldet Verbindungen mit <code>itemType</code> <code>connection</code> und ihrem Index in <code>connections</code>.</li><li>Fehlercodes einer Verbindung: <code>SOURCE_REQUIRED</code>, <code>SOURCE_AMBIGUOUS</code>, <code>SOURCE_NOT_FOUND</code> und <code>SOURCE_NOT_ALLOWED</code> (dasselbe mit <code>TARGET_</code>), <code>METATYPE_NOT_CONNECTION</code> und <code>ENDPOINT_CHANGE_NOT_SUPPORTED</code>. Eine Entität eines Verbindungstyps in <code>entities</code> wird mit <code>METATYPE_IS_CONNECTION</code> abgelehnt.</li></ul><p>Eine einzelne Verbindung legst du mit <code>POST /api/v1/connections</code> und denselben Feldern an; die Antwort (<code>201</code>) enthält die Verbindung mit Quelle und Ziel. Fehlt Quelle oder Ziel, kommt <code>404</code>, bei anderen Fehlern <code>422</code>.</p><p><code>GET /metamodel/allowed-connections?sourceMetatypeId=…&amp;targetMetatypeId=…</code> sagt dir vorab, welche Verbindungstypen zwei Entitätstypen verbinden dürfen.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};